// SPDX-License-Identifier: Apache-2.0
// e1_carry_chain.S — E1: 加法器最长进位链
//
// 模板（plan E1，对应设计概念"操作数翻转率最大化 + 进位链极限", weak 因素②老化）:
//   强制加法器进位信号从 bit0 传播到 bit63（最长组合逻辑路径），延迟最大、
//   最易被时序违例击穿。配合 32/48 位进位边界变异，覆盖不同进位链长度。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 变体1: 64 位全进位链 (0xFFF..F + 1 = 0, C=1)
    // CSP: carry_chain
    // MUT: carry_chain
    LOAD_ALL_ONES  x1
    mov     x2, #1
    adds    x0, x1, x2          // 进位 bit0→bit63, x0=0, C=1
    // SDC 验证: x0=0, NZCV.C=1

    // 变体2: 32 位进位边界 (0x00000000FFFFFFFF + 1)
    LOAD_CARRY32   x3
    mov     x4, #1
    adds    x5, x3, x4          // 32→64 位进位传播边界, x5=0x100000000

    // 变体3: 48 位进位链 (0x0000FFFFFFFFFFFF + 1)
    LOAD_CARRY48   x6
    mov     x7, #1
    adds    x8, x6, x7          // 48 位进位链, x8=0x0001000000000000

    // 变体4: 最大正 + 1 (有符号溢出, 测 NZCV flags 生成逻辑)
    LOAD_MAX_POS   x9
    mov     x10, #1
    adds    x11, x9, x10        // 0x7FFF..F + 1 = 0x8000..0, V=1(溢出), N=1
    // SDC 验证: x11=0x8000000000000000, NZCV.V=1

    // 变体5: 单 bit 游走进位 (bit 31)
    mov     x12, #0x80000000
    mov     x13, #0x80000000
    adds    x14, x12, x13       // bit31 进位 → bit32, x14=0x100000000

====asm_common====
// SPDX-License-Identifier: Apache-2.0
// asm_common.S.inc — SDC 检测用例公共汇编宏
//
// 设计概念落地：操作数空间变异的工程化载体。这些宏把"构造一个 64-bit
// 极端操作数"从多条 movz/movk 序列封装成单行调用，使各模板可被操作数
// 变异引擎 (operand_mutator.py) 系统性展开为笛卡尔积变体。
//
// AArch64 调用约定提示（snap_tool --raw 注入的初值）：
//   x6  = data1_range.base (0x7'0000'0000, 4MB, 初值全 0)
//   x7  = data2_range.base (0x1007'0000'0000, 4MB, 初值全 0)
//   sp  = 0x200'1000 (栈顶)
//   其余寄存器 = 0；代码放 code_range，退出序列由 snap_tool 自动追加。
// 寻址约束：stp/ldp 仅 [Xn,#imm(8倍数)] 或 [Xn]，不接受 [Xn,Xm]。
//           跨边界访问须先 add 计算非对齐地址到寄存器，再 [reg]。

    .macro MOVK_ALL  rd, hi16, lo16
        // 构造 64-bit 常量 = (hi16 << 32) | lo16  （hi16/lo16 各 16 位）
        // 等价: rd = (hi16:hi16 << 32) | (lo16:lo16)？不——这里 hi16/lo16
        //   分别代表高 32 位和低 32 位的同一 16-bit 模式（用于 0xFFFF.../0x5555.../0xAAAA...）。
        // 对于需要异高低半的值，用 LOAD_IMM64 显式给 4 个 16-bit 段。
        movz    \rd, #\lo16, lsl #0
        movk    \rd, #\lo16, lsl #16
        movk    \rd, #\hi16, lsl #32
        movk    \rd, #\hi16, lsl #48
    .endm

    .macro LOAD_IMM64 rd, s0, s1, s2, s3
        // 构造任意 64-bit 立即数，4 个 16-bit 段 s0(lsl0)..s3(lsl48)
        movz    \rd, #\s0, lsl #0
        movk    \rd, #\s1, lsl #16

