#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""vault.py — Vault JSONL 持久层 + 血缘 (sdc_pipeline R5 解法)。

scheme.md Layer 2 "Vault 持久化 + 血缘" 的第一版实现:
- candidates.jsonl  / assessments.jsonl 两个追加式 JSONL 文件
- 幂等 put (按 ident / ident+evaluator 去重)
- 血缘回溯 lineage() 沿 parents 链回到 seed
- top_by(metric) 供 Filter / 报告查询

选 JSONL 而非 SQLite: 与现有实验 JSON 输出一致、可 git diff、零依赖。
"""
import json
import os
from dataclasses import dataclass, asdict

from tools.sdc_pipeline.candidate import Candidate


@dataclass
class Assessment:
    """一次评估记录: 候选 ident + 指标 dict + 评估器名 (+可选 gem5 验证结果)。"""
    ident: str
    metrics: dict
    evaluator: str
    validated: dict | None = None  # 第二阶段: {bit: {...}, struct: {...}}


class Vault:
    def __init__(self, root: str):
        self.root = root
        os.makedirs(root, exist_ok=True)
        self.cand_path = os.path.join(root, "candidates.jsonl")
        self.assess_path = os.path.join(root, "assessments.jsonl")
        # 内存索引: ident → 记录; (ident, evaluator) → 记录
        self._cands: dict[str, dict] = {}
        self._assess: dict[tuple, dict] = {}
        self._children: dict[str, list[str]] = {}
        self._load()

    # ---- 持久化 ----
    def _load(self):
        if os.path.exists(self.cand_path):
            with open(self.cand_path) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    rec = json.loads(line)
                    self._cands[rec["ident"]] = rec
        if os.path.exists(self.assess_path):
            with open(self.assess_path) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    rec = json.loads(line)
                    self._assess[(rec["ident"], rec["evaluator"])] = rec

    def _append(self, path: str, rec: dict):
        with open(path, "a") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    # ---- Candidate ----
    def put_candidate(self, c: Candidate):
        if c.ident in self._cands:
            return  # 幂等
        rec = {"ident": c.ident, "source_asm": c.source_asm,
               "regs_init": {str(k): v for k, v in c.regs_init.items()},
               "parents": c.parents, "origin": c.origin,
               "structure_tags": c.structure_tags}
        self._cands[c.ident] = rec
        for p in c.parents:
            self._children.setdefault(p, []).append(c.ident)
        self._append(self.cand_path, rec)

    def get(self, ident: str) -> Candidate | None:
        rec = self._cands.get(ident)
        if rec is None:
            return None
        return Candidate(ident=rec["ident"], source_asm=rec["source_asm"],
                         code_bytes=b"",  # bytes 不持久化 (可由 asm 重编译)
                         regs_init={int(k): v for k, v in rec["regs_init"].items()},
                         parents=rec["parents"], origin=rec["origin"],
                         structure_tags=rec["structure_tags"])

    def count_candidates(self) -> int:
        return len(self._cands)

    def children(self, ident: str) -> list[str]:
        return list(self._children.get(ident, []))

    def lineage(self, ident: str) -> list[str]:
        """回溯血缘链: [self, parent, grandparent, ..., seed]。"""
        chain = []
        cur = ident
        seen = set()
        while cur and cur in self._cands and cur not in seen:
            seen.add(cur)
            chain.append(cur)
            parents = self._cands[cur]["parents"]
            cur = parents[0] if parents else None
        return chain

    # ---- Assessment ----
    def put_assessment(self, a: Assessment):
        key = (a.ident, a.evaluator)
        if key in self._assess:
            return  # 幂等 (同候选同评估器)
        rec = {"ident": a.ident, "metrics": a.metrics,
               "evaluator": a.evaluator, "validated": a.validated}
        self._assess[key] = rec
        self._append(self.assess_path, rec)

    def count_assessments(self) -> int:
        return len(self._assess)

    def top_by(self, metric: str, k: int) -> list[tuple[str, float]]:
        """按指标降序取前 k (缺该指标的记录跳过)。"""
        rows = []
        for (ident, _ev), rec in self._assess.items():
            if metric in rec["metrics"]:
                rows.append((ident, rec["metrics"][metric]))
        rows.sort(key=lambda x: -x[1])
        return rows[:k]

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""filters.py — 多指标筛选器 (sdc_pipeline Filter 层)。

- WeightedFilter: 指标加权和降序取 top-k
- ParetoFilter:  非支配排序 (NSGA 风格第一层), scheme §5.1 跨结构联合优化的
  "Pareto 最优序列集" 的高功耗/高覆盖筛选实现
"""
from tools.sdc_pipeline.vault import Assessment


def _metric_get(a: Assessment, name: str):
    return a.metrics.get(name)


class WeightedFilter:
    """Σ w_i * metric_i 加权和, 降序取 top-k。缺指标的候选该指标记 0。"""
    def __init__(self, weights: dict):
        self.weights = weights

    def score(self, a: Assessment) -> float:
        return sum(w * (a.metrics.get(m, 0.0) or 0.0)
                   for m, w in self.weights.items())

    def select(self, rows: list, k: int) -> list:
        scored = sorted(rows, key=lambda ca: -self.score(ca[1]))
        return [c for c, _ in scored[:k]]


class ParetoFilter:
    """非支配筛选: 保留非支配前沿 (全部 maximize 指标)。"""
    def __init__(self, maximize: list):
        self.maximize = maximize

    def _dominates(self, a: Assessment, b: Assessment) -> bool:
        """a 支配 b: 所有指标 >= 且至少一个 >。缺指标记 0。"""
        ge = all(_metric_get(a, m) >= _metric_get(b, m) for m in self.maximize)
        gt = any(_metric_get(a, m) > _metric_get(b, m) for m in self.maximize)
        return ge and gt

    def select(self, rows: list, k: int) -> list:
        fronts = []
        for c, a in rows:
            if not any(self._dominates(b[1], a) for _, b in rows if (c, a) != (b[0], b[1])):
                fronts.append(c)
        return fronts[:k]

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""pipeline.py — 轻量闭环编排器 (sdc_pipeline 首里程碑 M1)。

Gen → Assess → Filter → Feedback 循环:
  每代: policy 选 mutators → 变异 → 评估器池评估 → Filter 选 top-k
        进入下代种子池 → Vault 全程落盘

policy = RL 接入口 (Gym 语义): choose_mutators(state) 相当于 action,
observe(generation, mutator_scores, baseline) 相当于 reward 反馈。
第一版 HillClimbPolicy (启发式权重调整), 后续换 RL policy 对象即可,
框架其余不变 — scheme §5.2 "可演进" 的落点。

gem5+CHAOS 检出率验证 (validate 阶段) 由 validator 参数接入 (Task 6/7),
无 validator 时为纯 Unicorn 轻量闭环 (先轻后重策略)。
"""
import random
from dataclasses import dataclass, field

from tools.sdc_pipeline.vault import Vault, Assessment


@dataclass
class GenerationReport:
    generation: int
    produced: int
    metrics_mean: dict = field(default_factory=dict)
    mutator_scores: dict = field(default_factory=dict)


@dataclass
class PipelineReport:
    generations: list = field(default_factory=list)
    final_top: list = field(default_factory=list)


class HillClimbPolicy:
    """启发式策略: 上代各 mutator 的 (子代指标均值 - 全体基线) 反馈调权。

    score 高的 mutator 权重 × (1 + lr*score), 再归一。这是 RL policy 的
    占位实现 — 接口与 RL 策略对象完全同构 (choose_mutators / observe)。
    """
    def __init__(self, mutator_names: list, lr: float = 0.5):
        self.names = list(mutator_names)
        self.lr = lr
        self.weights = {m: 1.0 for m in self.names}

    def observe(self, generation: int, mutator_scores: dict, baseline: float):
        """mutator_scores: {mutator_name: 该 mutator 子代指标均值};
        baseline: 全体子代均值。相对提升→加权。"""
        for m, s in mutator_scores.items():
            if m in self.weights:
                self.weights[m] *= (1.0 + self.lr * (s - baseline))
        # 归一并保持 >0
        total = sum(self.weights.values()) or 1.0
        for m in self.weights:
            self.weights[m] = max(0.05, self.weights[m] / total)

    def choose_mutators(self, rng: random.Random) -> list:
        """全部 mutator 参与 (权重影响下一代选择, 第一版不丢弃)。"""
        return list(self.names)


class Pipeline:
    def __init__(self, seeds: list, mutators: list, evaluators: list,
                 filt, vault: Vault, policy, rng_seed: int = 42,
                 validator=None):
        self.seeds = list(seeds)
        self.mutators = list(mutators)
        self.evaluators = list(evaluators)
        self.filt = filt
        self.vault = vault
        self.policy = policy
        self.rng = random.Random(rng_seed)
        self.validator = validator  # Task 6/7: gem5_runner 注入验证器 (可选)

        for s in self.seeds:
            self.vault.put_candidate(s)

    def _assess(self, cand) -> Assessment:
        metrics = {}
        for ev in self.evaluators:
            metrics.update(ev.evaluate(cand))
        return Assessment(ident=cand.ident, metrics=metrics,
                          evaluator="+".join(ev.name for ev in self.evaluators))

    def run(self, generations: int, per_gen_mutations: int, top_k: int) -> PipelineReport:
        report = PipelineReport()
        pool = list(self.seeds)  # 当前代种子池
        for gen in range(1, generations + 1):
            chosen = self.policy.choose_mutators(self.rng)
            mutators = [m for m in self.mutators if m.name in chosen]
            # Gen: 变异
            children = []
            for m in mutators:
                for _ in range(per_gen_mutations):
                    parent = self.rng.choice(pool)
                    kids = m.mutate(parent, self.rng)
                    children += kids[:1]  # 每次变异取 1 子代 (控量)
            for c in children:
                self.vault.put_candidate(c)
            # Assess: 评估
            assessed = [(c, self._assess(c)) for c in children]
            for _, a in assessed:
                self.vault.put_assessment(a)
            # Feedback: policy 观察 (mutator 分组均值 vs 基线)
            all_scores = [self.filt.score(a) for _, a in assessed]
            baseline = sum(all_scores) / len(all_scores) if all_scores else 0.0
            mut_scores = {}
            for m in mutators:
                kids_of_m = [a for c, a in assessed
                             if c.origin == f"mutate:{m.name}"]
                if kids_of_m:
                    mut_scores[m.name] = sum(self.filt.score(a) for a in kids_of_m) / len(kids_of_m)
            self.policy.observe(gen, mut_scores, baseline)
            # Filter: top-k 进入下代
            if assessed:
                pool = self.filt.select(assessed, top_k)
            # 报告
            metrics_mean = {}
            for _, a in assessed:
                for mk, mv in a.metrics.items():
                    metrics_mean.setdefault(mk, []).append(mv)
            metrics_mean = {k: sum(v) / len(v) for k, v in metrics_mean.items()}
            report.generations.append(GenerationReport(
                generation=gen, produced=len(children),
                metrics_mean=metrics_mean, mutator_scores=mut_scores))
        # 终榜 (Vault 全量 top)
        report.final_top = self.vault.top_by(
            next(iter(self.evaluators[0].evaluate(pool[0]).keys()))
            if pool else "ace_proxy", 5)
        return report

