         "    stp x23, x24, [sp, #160]", "    stp x25, x26, [sp, #176]",
         "    stp x27, x28, [sp, #176+16]",
         "    str x0, [sp, #104]", "    str x1, [sp, #112]"]
    for i in range(nregs):
        L.append("    ldr x2, [sp, #104]")
        L.append(f"    ldr x{i}, [x2, #{i*8}]")
    for w in insns:
