    uint64_t acc = 0;
    for (int i = 0; i < 29; i++) acc += g_out[i];
    uint32_t crc = (uint32_t)(acc ^ (acc >> 32));
    printf("SUM=%llu CRC=%08x\\n", (unsigned long long)acc, crc);
    return 0;
}}
